<script setup>
import {newActivity} from './model.js';
import CompoundStep from './CompoundStep.vue';
import MediaField from './MediaField.vue';
const props=defineProps({form:Object,t:Function,busy:Boolean,base:String,language:String,rebost:Boolean,banks:Boolean});
const emit=defineEmits(['bank','image-error','image-busy']);
function removeCategory(index){props.form.categories.splice(index,1);props.form.items.forEach(item=>{if(item.category===index)item.category=0;else if(item.category>index)item.category--;});if(props.form.type==='ordering')props.form.categories.forEach((c,i)=>c.name=String(i+1));}
</script>
<template>
 <fieldset v-if="form.type==='multiple-choice'" id="answersField"><legend>{{t('answers')}}</legend><div id="answers"><div v-for="(answer,index) in form.answers" :key="index" class="answer-row"><input v-model="answer.text" class="answer-text" maxlength="500" :aria-label="t('answers')"><label class="correct"><input class="answer-correct" type="radio" name="correct" :checked="answer.correct" @change="form.answers.forEach((a,i)=>a.correct=i===index)"><span>✓</span></label><button type="button" class="remove" :aria-label="t('remove')" @click="form.answers.splice(index,1)">×</button></div></div><button id="addAnswer" type="button" class="button secondary" :disabled="form.answers.length>=8" @click="form.answers.push({text:'',correct:false})">{{t('addAnswer')}}</button></fieldset>
 <fieldset v-else-if="form.type==='true-false'" id="truthField"><legend>{{t('correctAnswer')}}</legend><label class="choice"><input id="correctTrue" v-model="form.correct" type="radio" name="truth" :value="true"><span>{{t('true')}}</span></label><label class="choice"><input id="correctFalse" v-model="form.correct" type="radio" name="truth" :value="false"><span>{{t('false')}}</span></label></fieldset>
 <fieldset v-else-if="form.type==='memory'" id="memoryField"><legend>{{t('pairs')}}</legend><div id="cards"><div v-for="(card,index) in form.cards" :key="index" class="answer-row memory-row"><div><input v-model="card.text" class="card-text" maxlength="120" :aria-label="t('pair')"><MediaField kind="image" :base="base" :t="t" :language="language" :rebost="rebost" :banks="banks" :label="t('imageLeft')" :value="card.image" :credit="card.imageCredit" @update:value="card.image=$event" @update:credit="card.imageCredit=$event" @busy="emit('image-busy',$event)" @error="emit('image-error')" /><MediaField kind="audio" :base="base" :t="t" :language="language" :rebost="rebost" :banks="banks" :label="t('media.audio')" :value="card.audio" :credit="card.audioCredit" @update:value="card.audio=$event" @update:credit="card.audioCredit=$event" @busy="emit('image-busy',$event)" @error="emit('image-error')" /></div><button type="button" class="remove" :aria-label="t('remove')" @click="form.cards.splice(index,1)">×</button></div></div><button id="addCard" type="button" class="button secondary" :disabled="form.cards.length>=12" @click="form.cards.push({text:'',image:'',imageCredit:'',audio:'',audioCredit:''})">{{t('addPair')}}</button></fieldset>
 <fieldset v-else-if="form.type==='matching'" id="matchingField"><legend>{{t('relations')}}</legend><div id="matches"><div v-for="(pair,index) in form.pairs" :key="index" class="answer-row matching-row"><div v-for="side in ['left','right']" :key="side"><input v-model="pair[side]" :class="'match-'+side" maxlength="120" :aria-label="t(side)"><MediaField kind="image" :base="base" :t="t" :language="language" :rebost="rebost" :banks="banks" :label="t(side==='left'?'imageLeft':'imageRight')" :value="pair[side+'Image']" :credit="pair[side+'ImageCredit']" @update:value="pair[side+'Image']=$event" @update:credit="pair[side+'ImageCredit']=$event" @busy="emit('image-busy',$event)" @error="emit('image-error')" /></div><button type="button" class="remove" :aria-label="t('remove')" @click="form.pairs.splice(index,1)">×</button></div></div><button id="addMatch" type="button" class="button secondary" :disabled="form.pairs.length>=8" @click="form.pairs.push({left:'',right:'',leftImage:'',leftImageCredit:'',rightImage:'',rightImageCredit:''})">{{t('addRelation')}}</button></fieldset>
 <fieldset v-else-if="['classify','ordering'].includes(form.type)" id="classifyField" :class="{'ordering-mode':form.type==='ordering'}"><legend>{{t(form.type==='ordering'?'positions':'categories')}}</legend><div id="categories"><div v-for="(category,index) in form.categories" :key="index" class="answer-row"><input v-model="category.name" class="category-name" maxlength="120" :readonly="form.type==='ordering'" :aria-label="t('category')"><button type="button" class="remove" :aria-label="t('remove')" @click="removeCategory(index)">×</button></div></div><button id="addCategory" type="button" class="button secondary" :disabled="form.categories.length>=12" @click="form.categories.push({name:form.type==='ordering'?String(form.categories.length+1):''})">{{t(form.type==='ordering'?'addPosition':'addCategory')}}</button><legend>{{t(form.type==='ordering'?'steps':'items')}}</legend><div id="classifyItems"><div v-for="(item,index) in form.items" :key="index" class="answer-row classify-row"><div><input v-model="item.text" class="classify-text" maxlength="120" :aria-label="t('item')"><MediaField kind="image" :base="base" :t="t" :language="language" :rebost="rebost" :banks="banks" :label="t('imageLeft')" :value="item.image" :credit="item.imageCredit" @update:value="item.image=$event" @update:credit="item.imageCredit=$event" @busy="emit('image-busy',$event)" @error="emit('image-error')" /></div><select v-model.number="item.category" class="classify-category" :aria-label="t('category')"><option v-for="(category,i) in form.categories" :key="i" :value="i">{{category.name||t('category')+' '+(i+1)}}</option></select><button type="button" class="remove" :aria-label="t('remove')" @click="form.items.splice(index,1)">×</button></div></div><button id="addClassifyItem" type="button" class="button secondary" :disabled="form.items.length>=12" @click="form.items.push({text:'',category:0,image:'',imageCredit:''})">{{t(form.type==='ordering'?'addStep':'addItem')}}</button></fieldset>
 <fieldset v-else-if="['fill-blanks','drag-text','mark-words'].includes(form.type)" :id="({'fill-blanks':'fillBlanks','drag-text':'dragText','mark-words':'markWords'})[form.type]+'Field'"><legend>{{t(form.type==='fill-blanks'?'fillText':form.type==='drag-text'?'dragTextText':'markWordsText')}}</legend><textarea :id="({'fill-blanks':'fillBlanks','drag-text':'dragText','mark-words':'markWords'})[form.type]+'Text'" v-model="form.text" maxlength="5000"></textarea><small>{{t('fillHint')}}</small></fieldset>
 <fieldset v-else-if="form.type==='find-words'" id="findWordsField"><legend>{{t('findWordsList')}}</legend><div id="findWords"><div v-for="(_,index) in form.words" :key="index" class="answer-row"><input v-model="form.words[index]" class="find-word" maxlength="15" :aria-label="t('findWordsPlaceholder')"><button type="button" class="remove" :aria-label="t('remove')" @click="form.words.splice(index,1)">×</button></div></div><button id="addFindWord" type="button" class="button secondary" :disabled="form.words.length>=12" @click="form.words.push('')">{{t('addWord')}}</button></fieldset>
 <fieldset v-else-if="form.type==='dialog-cards'" id="dialogCardsField"><legend>{{t('dialogCardsList')}}</legend><div id="dialogCards"><div v-for="(card,index) in form.cards" :key="index" class="answer-row dialog-row"><div><input v-model="card.front" class="dialog-front" maxlength="500" :aria-label="t('dialogFront')"><input v-model="card.back" class="dialog-back" maxlength="500" :aria-label="t('dialogBack')"><MediaField kind="audio" :base="base" :t="t" :language="language" :rebost="rebost" :banks="banks" :label="t('media.audio')" :value="card.audio" :credit="card.audioCredit" @update:value="card.audio=$event" @update:credit="card.audioCredit=$event" @busy="emit('image-busy',$event)" @error="emit('image-error')" /></div><button type="button" class="remove" :aria-label="t('remove')" @click="form.cards.splice(index,1)">×</button></div></div><button id="addDialogCard" type="button" class="button secondary" :disabled="form.cards.length>=15" @click="form.cards.push({front:'',back:'',audio:'',audioCredit:''})">{{t('addDialogCard')}}</button></fieldset>
 <fieldset v-else-if="form.type==='crossword'" id="crosswordField"><legend>{{t('crosswordList')}}</legend><div id="crosswordWords"><div v-for="(word,index) in form.words" :key="index" class="answer-row"><input v-model="word.answer" class="crossword-answer" maxlength="20" :aria-label="t('crosswordAnswer')"><input v-model="word.clue" class="crossword-clue" maxlength="300" :aria-label="t('crosswordClue')"><button type="button" class="remove" :aria-label="t('remove')" @click="form.words.splice(index,1)">×</button></div></div><button id="addCrosswordWord" type="button" class="button secondary" :disabled="form.words.length>=10" @click="form.words.push({answer:'',clue:''})">{{t('addCrosswordWord')}}</button></fieldset>
 <fieldset v-else-if="form.type==='compound'" id="compoundField"><legend>{{t('compound.steps')}}</legend><div id="compoundSteps"><CompoundStep v-for="(step,index) in form.activities" :key="step" :step="step" :index="index" :t="t" :disabled="busy" @remove="form.activities.splice(index,1)" /></div><button id="addCompoundStep" type="button" class="button secondary" :disabled="form.activities.length>=10" @click="form.activities.push(newActivity())">{{t('compound.add')}}</button><button id="addCompoundFromBank" type="button" class="button secondary" :disabled="form.activities.length>=10" @click="emit('bank')">{{t('bank.add')}}</button><label><span>{{t('compound.pass')}}</span><input id="compoundPass" v-model.number="form.passPercentage" type="number" min="0" max="100"></label><label class="choice"><input id="compoundRandom" v-model="form.randomQuestions" type="checkbox"><span>{{t('compound.random')}}</span></label></fieldset>
</template>
